import { chromium } from '@playwright/test'
const b = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE, headless: true })
async function grab(url, prep, sel) {
  const p = await (await b.newContext({ viewport: { width: 390, height: 844 } })).newPage()
  await p.goto(url, { waitUntil: 'domcontentloaded' })
  if (prep) await prep(p)
  await p.waitForTimeout(2500)
  const r = await p.evaluate((sel) => {
    const el = document.querySelector(sel)
    if (!el) return null
    const cs = getComputedStyle(el)
    return { tag: el.tagName, text: el.textContent.trim().slice(0, 12), ff: cs.fontFamily, fw: cs.fontWeight, fs: cs.fontSize, color: cs.color, lh: cs.lineHeight }
  }, sel)
  await p.close()
  return r
}
