import { chromium } from '@playwright/test'
const b = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE, headless: true })
const p = await (await b.newContext({ viewport: { width: 390, height: 844 } })).newPage()
await p.setContent('<div id="t">x</div>')
const r = await p.evaluate(() => {
  const sample = '\u96e8\u6c34\u7be6\u3001\u96c6\u6c34\u4e95\u662f\u5426\u6de4\u5835'
  function mk(ff) {
    const s = document.createElement('span')
    s.style.font = '700 14px ' + ff
    s.textContent = sample
    s.style.position = 'absolute'
    document.body.appendChild(s)
    const cs = getComputedStyle(s)
    const w = Math.round(s.getBoundingClientRect().width)
    const out = { ff, usedFF: cs.fontFamily, w }
    s.remove()
    return out
  }
  return [
    mk('"Noto Sans SC:Medium"'),
    mk('"Noto Sans SC:Medium",sans-serif'),
    mk('sans-serif'),
    mk('serif'),
  ]
})
console.log(JSON.stringify(r, null, 1))
await b.close()

