import { chromium } from '@playwright/test'
const b = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE, headless: true })

function summarize(page) {
  return page.evaluate(() => {
    const root = document.querySelector('.ui-ref8443') || document.body
    const rootCS = getComputedStyle(root)
    // 采样多种文本元素
    const sels = ['h1', '.section-title span, .section-title', '.choice-label b, .choice-b', '.detail-card h3', '.status', '.btn', '.toggle-btn', '.counter-val', '.meta, p', 'label, .required-label']
    const out = { rootFss: rootCS.fontSynthesis, rootFF: rootCS.fontFamily, samples: {} }
    for (const s of sels) {
      const el = document.querySelector(s)
      if (!el) continue
      const cs = getComputedStyle(el)
      out.samples[s] = { ff: cs.fontFamily, fw: cs.fontWeight, fs: cs.fontSize }
    }
    return out
  })
}

async function run(url, prep) {
  const p = await (await b.newContext({ viewport: { width: 390, height: 844 } })).newPage()
  await p.goto(url, { waitUntil: 'domcontentloaded' })
  if (prep) await prep(p)
  await p.waitForTimeout(1500)
  const r = await summarize(p)
  await p.close()
  return r
}

// mid page
const refMid = await run('http://localhost:8443/', async p => { await p.waitForTimeout(400); await p.getByRole('button', { name: '汛中巡检' }).click(); await p.getByRole('button', { name: '继续填报' }).first().click(); await p.waitForSelector('.form-page') })
const mineMid = await run('http://127.0.0.1:8095/#/pages/inspection/index?kind=mid')
console.log('=== 汛中 root fss ===')
console.log('REF', refMid.rootFss, '| MINE', mineMid.rootFss)
console.log('=== 各元素对比 (ff / fw / fs) ===')
const keys = new Set([...Object.keys(refMid.samples), ...Object.keys(mineMid.samples)])
for (const k of keys) {
  console.log('[' + k + ']')
  console.log('  REF ', JSON.stringify(refMid.samples[k]))
  console.log('  MINE', JSON.stringify(mineMid.samples[k]))
}
await b.close()

