import { chromium } from '@playwright/test'
const b = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE, headless: true })
async function sample(url, prep) {
  const p = await (await b.newContext({ viewport: { width: 390, height: 844 } })).newPage()
  await p.goto(url, { waitUntil: 'domcontentloaded' })
  if (prep) await prep(p)
  await p.waitForTimeout(1500)
  const r = await p.evaluate(() => {
    const sels = ['h1', '.section-title', '.card-h3, .card h3', '.detail-card h3', '.required-label', '.required-label small, .label-small', '.ref-textarea', '.ref-input', '.status', '.urgency', '.level-btn, .level-row button', '.upload-label, .uploads + h3', '.hint']
    const out = {}
    for (const s of sels) {
      const el = document.querySelector(s)
      if (!el) continue
      const cs = getComputedStyle(el)
      out[s] = cs.fontWeight + ' / ' + cs.fontSize + ' / ' + cs.fontFamily.split(',')[0]
    }
    return out
  })
  await p.close()
  return r
}
const pages = [
  ['汛前', 'http://127.0.0.1:8095/#/pages/inspection/index?kind=pre', 'http://localhost:8443/', async (p) => { await p.waitForTimeout(400); await p.getByRole('button', { name: '继续填报' }).first().click(); await p.waitForSelector('.form-page') }],
  ['求援', 'http://127.0.0.1:8095/#/pages/rescue/index', 'http://localhost:8443/', async (p) => { await p.waitForTimeout(400); await p.getByRole('button', { name: '汛中巡检' }).click(); await p.getByRole('button', { name: '继续填报' }).first().click(); await p.waitForSelector('.floating-rescue'); await p.getByRole('button', { name: '紧急求救' }).click(); await p.waitForSelector('.form-page') }],
  ['详情', 'http://127.0.0.1:8095/#/pages/detail/index?id=FX-20260712-0005&kind=pre', 'http://localhost:8443/', async (p) => { await p.waitForTimeout(400); await p.getByRole('button', { name: '查看详情' }).first().click(); await p.waitForTimeout(600) }],
]
for (const [name, mineUrl, refUrl, refPrep] of pages) {
  const ref = await sample(refUrl, refPrep)
  const mine = await sample(mineUrl)
  console.log('===== ' + name + ' =====')
  const keys = new Set([...Object.keys(ref), ...Object.keys(mine)])
  for (const k of keys) {
    const a = ref[k] || '-', c = mine[k] || '-'
    const flag = a === c ? 'OK ' : 'DIFF'
    if (flag === 'DIFF') console.log('  ' + flag + ' [' + k + '] REF=' + a + ' | MINE=' + c)
  }
}
await b.close()

